#import "../RWEntityCreditPolicy.h"
#import "../RWDiscoveryMetadataPolicy.h"
static NSDictionary *Claim(id value){return @{@"mainsnak":@{@"datavalue":@{@"value":value}}};}
int main(int argc,const char **argv){@autoreleasepool{int checks=0,failures=0;
#define CHECK(...) do{checks++;if(!(__VA_ARGS__)){failures++;fprintf(stderr,"FAIL line %d\n",__LINE__);}}while(0)
    NSDictionary *company=@{@"id":@"Q10",@"name":@"A company",@"type":@"studio",@"creditRole":@"studio",@"biography":@"Keep this biography",@"image":@"https://image.test/logo.png",@"facts":@[@{@"label":@"Founded",@"value":@"2000"}]};
    CHECK([RWEntityCreditPolicy isCompany:company]);CHECK([[RWEntityCreditPolicy roles:company]isEqual:@[@"studio",@"distributor",@"network"]]);
    for(NSString *role in [RWEntityCreditPolicy roles:company]){NSDictionary *changed=[RWEntityCreditPolicy selectRole:role entity:company];CHECK([changed[@"creditRole"]isEqual:role]);CHECK([changed[@"biography"]isEqual:company[@"biography"]]&&[changed[@"facts"]isEqual:company[@"facts"]]&&[changed[@"image"]isEqual:company[@"image"]]);}
    CHECK([company[@"creditRole"]isEqual:@"studio"]);CHECK(![RWEntityCreditPolicy selectRole:@"cast" entity:company]);CHECK(![RWEntityCreditPolicy selectRole:@"invalid" entity:company]);
    NSDictionary *person=@{@"id":@"Q11",@"type":@"person",@"creditRole":@"director"};CHECK(![RWEntityCreditPolicy isCompany:person]);CHECK([[RWEntityCreditPolicy roles:person]isEqual:@[@"cast",@"director"]]);CHECK(![RWEntityCreditPolicy selectRole:@"network" entity:person]);CHECK([[RWEntityCreditPolicy selectRole:@"cast" entity:person][@"creditRole"]isEqual:@"cast"]);
    CHECK([RWEntityCreditPolicy isCompany:@{@"id":@"Q10",@"creditRole":@"distributor"}]);CHECK(![RWEntityCreditPolicy isCompany:@{@"id":@"Q11",@"type":@"person",@"creditRole":@"network"}]);
    CHECK([[RWEntityCreditPolicy heading:@"network"]isEqual:@"Original broadcast credits"]);CHECK(![RWEntityCreditPolicy property:@"unknown"]);CHECK(![RWEntityCreditPolicy field:nil]);CHECK([[RWEntityCreditPolicy companySummary:@[@"network",@"studio",@"distributor",@"studio"]]isEqual:@"Production · Distribution · Original broadcaster"]);
    NSDictionary *title=@{@"id":@"Q20",@"claims":@{@"P272":@[Claim(@{@"id":@"Q10"})],@"P750":@[Claim(@{@"id":@"Q12"})],@"P449":@[Claim(@{@"id":@"Q13"})],@"P345":@[Claim(@"tt20")]}};
    for(NSArray *pair in @[@[@"studio",@"Q10",@"P272",@"studios"],@[@"distributor",@"Q12",@"P750",@"distributors"],@[@"network",@"Q13",@"P449",@"networks"]]){CHECK([[RWEntityCreditPolicy property:pair[0]]isEqual:pair[2]]&&[[RWEntityCreditPolicy field:pair[0]]isEqual:pair[3]]);CHECK([[RWDiscoveryMetadataPolicy creditIDs:title role:pair[0] entityID:pair[1]]isEqual:@[@"tt20"]]);for(NSString *other in @[@"Q10",@"Q12",@"Q13"])if(![other isEqual:pair[1]])CHECK(![RWDiscoveryMetadataPolicy creditIDs:title role:pair[0] entityID:other].count);}
    if(argc>1){NSString *folder=[NSString stringWithUTF8String:argv[1]];NSDictionary *entities=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:[folder stringByAppendingPathComponent:@"entities.json"]] options:0 error:nil][@"entities"],*audit=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:[folder stringByAppendingPathComponent:@"claims-audit.json"]] options:0 error:nil];CHECK(entities.count>=3&&[audit[@"verified"]count]>=4);for(NSDictionary *row in audit[@"verified"]){NSArray *verified=[RWDiscoveryMetadataPolicy creditIDs:entities[row[@"id"]] role:row[@"role"] entityID:@"Q16248298"];CHECK(verified.count==1&&[verified isEqual:row[@"imdb"]]);}}
    printf("{\"checks\":%d,\"failures\":%d}\n",checks,failures);return failures?1:0;
}}
